"""Flashy, simplified live command-center overlay for Ember operations."""
from __future__ import annotations


def install_sprint41_ux(app):
    @app.after_request
    def enhance(response):
        if response.status_code != 200 or not response.is_sequence:
            return response
        try:
            from flask import request

            if request.path != "/platform/control-tower":
                return response
            html = response.get_data(as_text=True)
            if "s41-command-center" in html or "</body>" not in html.lower():
                return response

            style = r'''<style id="s41-command-center">
:root{--ember:#ff7a45;--ember2:#ffb347;--cyan:#58d6ff;--green:#45e0a8;--ink:#06152d}
.s41-shell{position:relative;overflow:hidden;margin:0 0 16px;padding:22px;border:1px solid #58d6ff33;border-radius:22px;background:radial-gradient(circle at 85% 5%,#ff7a452b,transparent 34%),linear-gradient(145deg,#081b3a,#07152d 62%,#0a2444);box-shadow:0 20px 70px #0008,inset 0 1px #ffffff10}
.s41-shell:before{content:'';position:absolute;inset:-40%;background:conic-gradient(from 180deg,transparent,#58d6ff12,transparent,#ff7a4518,transparent);animation:s41spin 18s linear infinite;pointer-events:none}
.s41-top,.s41-grid,.s41-feed,.s41-actions{position:relative;z-index:1}.s41-top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.s41-brand{display:flex;gap:14px;align-items:center}.s41-orb{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;font-size:27px;background:radial-gradient(circle at 35% 30%,#fff,#ffbf73 14%,#ff7043 45%,#7e183d 75%);box-shadow:0 0 0 6px #ff7a4514,0 0 38px #ff7a4570;animation:s41pulse 2.2s ease-in-out infinite}.s41-title{margin:0;font-size:24px}.s41-sub{margin:4px 0 0;color:#9bb1cf}.s41-live{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:999px;background:#45e0a814;color:#73efbd;font-size:12px;font-weight:800;border:1px solid #45e0a833}.s41-live i{width:8px;height:8px;border-radius:50%;background:#45e0a8;box-shadow:0 0 14px #45e0a8;animation:s41blink 1.2s infinite}.s41-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.s41-primary,.s41-secondary{border:0;border-radius:12px;padding:11px 15px;font-weight:800;cursor:pointer;transition:.2s}.s41-primary{background:linear-gradient(135deg,var(--ember),var(--ember2));color:#241002;box-shadow:0 8px 24px #ff7a4535}.s41-secondary{background:#ffffff0b;color:#d9e8ff;border:1px solid #ffffff16}.s41-primary:hover,.s41-secondary:hover{transform:translateY(-2px)}.s41-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:18px}.s41-card{position:relative;padding:15px;border:1px solid #ffffff12;border-radius:16px;background:linear-gradient(145deg,#ffffff0c,#ffffff04);cursor:pointer;transition:.2s;min-height:92px}.s41-card:hover{transform:translateY(-3px);border-color:#58d6ff55;box-shadow:0 12px 30px #0005}.s41-card span{display:block;color:#91a9c9;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.s41-card strong{display:block;margin-top:7px;font-size:27px}.s41-card small{color:#7190b8}.s41-card.running strong{color:var(--cyan)}.s41-card.good strong{color:var(--green)}.s41-card.hot strong{color:#ff9b6f}.s41-lower{position:relative;z-index:1;display:grid;grid-template-columns:1.4fr .8fr;gap:12px;margin-top:12px}.s41-panel{padding:16px;border:1px solid #ffffff12;border-radius:17px;background:#06162dbd}.s41-panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.s41-panel h3{margin:0;font-size:15px}.s41-feed{display:grid;gap:8px;max-height:285px;overflow:auto}.s41-event{display:grid;grid-template-columns:10px 1fr auto;gap:10px;align-items:start;padding:10px 11px;border-radius:12px;background:#ffffff07;border:1px solid transparent;cursor:pointer}.s41-event:hover{border-color:#58d6ff44}.s41-event i{width:8px;height:8px;border-radius:50%;margin-top:5px;background:#58d6ff;box-shadow:0 0 10px #58d6ff}.s41-event.done i{background:#45e0a8;box-shadow:0 0 10px #45e0a8}.s41-event.fail i{background:#ff6f88;box-shadow:0 0 10px #ff6f88}.s41-event b{font-size:12px}.s41-event p{margin:2px 0 0;color:#8ea6c6;font-size:11px}.s41-time{font-size:10px;color:#6f89aa;white-space:nowrap}.s41-status{display:grid;gap:9px}.s41-status-row{display:flex;justify-content:space-between;gap:12px;padding:10px;border-radius:12px;background:#ffffff07}.s41-status-row span{color:#8ea6c6}.s41-status-row b{font-size:12px}.s41-empty{padding:22px;text-align:center;color:#7f98ba;border:1px dashed #ffffff1a;border-radius:12px}.s41-toast{position:fixed;right:18px;bottom:18px;z-index:9999;padding:12px 16px;border-radius:12px;background:#0d2748;color:white;border:1px solid #58d6ff44;box-shadow:0 20px 45px #0008;opacity:0;transform:translateY(15px);transition:.25s}.s41-toast.show{opacity:1;transform:none}@keyframes s41spin{to{transform:rotate(360deg)}}@keyframes s41pulse{50%{transform:scale(1.06);box-shadow:0 0 0 10px #ff7a450d,0 0 48px #ff7a4580}}@keyframes s41blink{50%{opacity:.35}}@media(max-width:1000px){.s41-grid{grid-template-columns:repeat(2,1fr)}.s41-lower{grid-template-columns:1fr}}@media(max-width:620px){.s41-top{display:block}.s41-live{width:max-content;margin-top:12px}.s41-grid{grid-template-columns:1fr 1fr}.s41-shell{padding:15px}.s41-card strong{font-size:22px}}
</style>'''
            shell = r'''<section class="s41-shell" id="s41Command">
<div class="s41-top"><div><div class="s41-brand"><div class="s41-orb">🔥</div><div><h1 class="s41-title">Ember Command Center</h1><p class="s41-sub" id="s41Brief">Building your wholesale prospect pipeline from approved public sources.</p></div></div><div class="s41-actions"><button class="s41-primary" id="s41Queue">Queue Next Hunt</button><button class="s41-secondary" id="s41Review">Review Prospects</button><button class="s41-secondary" id="s41Refresh">Refresh Now</button></div></div><div class="s41-live"><i></i><span id="s41LiveLabel">EMBER ONLINE</span></div></div>
<div class="s41-grid"><div class="s41-card running" data-go="activeJobs" data-detail-href="/platform/details/jobs?status=active"><span>Active Jobs</span><strong id="s41Active">0</strong><small>View queued and running work</small></div><div class="s41-card good" data-go="completedJobs" data-detail-href="/platform/details/jobs?status=completed"><span>Completed Today</span><strong id="s41Done">0</strong><small>View today's completed work</small></div><div class="s41-card hot" data-go="review" data-detail-href="/platform/details/prospects?status=pending"><span>Pending Review</span><strong id="s41Pending">0</strong><small>Open prospects awaiting a decision</small></div><div class="s41-card" data-go="contacts" data-detail-href="/platform/details/contacts"><span>Contacts Found</span><strong id="s41Contacts">0</strong><small>View public contact records</small></div><div class="s41-card" data-go="companies" data-detail-href="/platform/details/companies"><span>Tracked Companies</span><strong id="s41Companies">0</strong><small>View company discovery history</small></div></div>
<div class="s41-lower"><div class="s41-panel"><div class="s41-panel-head"><h3>Live Ember activity</h3><span class="s41-time" id="s41Updated">Updating…</span></div><div class="s41-feed" id="s41Feed"><div class="s41-empty">Connecting to Ember…</div></div></div><div class="s41-panel"><div class="s41-panel-head"><h3>System at a glance</h3></div><div class="s41-status" id="s41Status"><div class="s41-empty">Checking worker health…</div></div></div></div>
</section><div class="s41-toast" id="s41Toast"></div>'''
            script = r'''<script id="s41-command-script">
(function(){
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function toast(msg){const n=$('s41Toast');n.textContent=msg;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2600)}
function switchTab(name){const routes={activeJobs:'/platform/details/jobs?status=active',completedJobs:'/platform/details/jobs?status=completed',review:'/platform/details/prospects?status=pending',contacts:'/platform/details/contacts',companies:'/platform/details/companies',emberLive:'/platform/details/activity',operations:'/platform/details/companies'};if(routes[name])window.location.href=routes[name];else{const b=document.querySelector('[data-tab="'+name+'"]');if(b)b.click()}}
function eventClass(t){t=String(t||'').toLowerCase();return t.includes('fail')?'fail':(t.includes('complete')||t.includes('discover'))?'done':''}
function eventText(x){return x.title||x.message||x.event_type||'Ember activity'}
async function loadS41(){try{const [o,q,w]=await Promise.all([api('/api/platform/sprint39/overview'),api('/api/platform/ember-queue?limit=20'),api('/api/platform/ember-workers')]);const s=q.summary||{},active=(s.Queued||0)+(s.Running||0);$('s41Active').textContent=active;$('s41Done').textContent=(o.health?.completed_24h||0);$('s41Pending').textContent=o.health?.pending_review||0;$('s41Contacts').textContent=o.health?.contacts||0;$('s41Companies').textContent=o.health?.tracked_companies||0;$('s41Brief').textContent=o.morning_brief?.summary||'Ember is building your prospect pipeline.';const events=(o.activity||[]).slice(0,10);$('s41Feed').innerHTML=events.length?events.map(x=>`<div class="s41-event ${eventClass(x.event_type)}" data-job="${x.job_id||''}"><i></i><div><b>${esc(eventText(x))}</b><p>${esc(x.detail||x.company_name||x.state||'')}</p></div><span class="s41-time">${x.created_at?new Date(x.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):''}</span></div>`).join(''):'<div class="s41-empty">Ember is ready. Queue the next hunt to begin.</div>';const worker=(w.items||[])[0];const healthy=worker&&!worker.stale&&worker.status!=='Failed';$('s41LiveLabel').textContent=healthy?'EMBER ONLINE':'EMBER CHECKING IN';$('s41Status').innerHTML=`<div class="s41-status-row"><span>Worker</span><b>${esc(worker?.status||'Starting')}</b></div><div class="s41-status-row"><span>Current job</span><b>${esc(worker?.current_job_id||'Waiting')}</b></div><div class="s41-status-row"><span>Queue</span><b>${active} active</b></div><div class="s41-status-row"><span>Outreach</span><b style="color:#45e0a8">Review gated</b></div><div class="s41-status-row"><span>Last heartbeat</span><b>${esc(worker?.last_heartbeat_at?new Date(worker.last_heartbeat_at).toLocaleTimeString():'Pending')}</b></div>`;$('s41Updated').textContent='Updated '+new Date().toLocaleTimeString();}catch(e){$('s41Feed').innerHTML='<div class="s41-empty">Live data is reconnecting…</div>';console.error(e)}}
async function queue(){const b=$('s41Queue');b.disabled=true;b.textContent='Queueing…';try{const r=await fetch('/api/platform/ember-queue/discovery',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company_limit:6,contact_limit:250})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not queue hunt');toast(`Ember hunt #${d.id} queued`);await loadS41()}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Queue Next Hunt'}}
document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('main')||document.querySelector('.content')||document.body;root.insertAdjacentHTML('afterbegin',`__SHELL__`);document.querySelectorAll('.s41-card[data-go]').forEach(x=>x.addEventListener('click',()=>switchTab(x.dataset.go)));$('s41Queue').onclick=queue;$('s41Review').onclick=()=>switchTab('review');$('s41Refresh').onclick=loadS41;loadS41();setInterval(loadS41,15000)});
})();
</script>'''.replace('__SHELL__', shell.replace('`','\\`'))
            html = html.replace('</head>', style + '</head>')
            pos = html.lower().rfind('</body>')
            html = html[:pos] + script + html[pos:]
            response.set_data(html)
            response.headers['Content-Length'] = str(len(response.get_data()))
        except Exception:
            app.logger.exception('Sprint 41 command center enhancement failed')
        return response

    return app
